	/** Все словари по идентификаторам локалей. */
	const DICTIONARIES = { ru, en, zh }

	/**
	 * Переводчик по умолчанию: русский словарь.
	 *
	 * Объявлен здесь, а не в потребителях, потому что все модули сборки попадают в
	 * один общий scope: два объявления с этим именем роняли бы весь бандл.
	 * Нужен там, где настоящий `t` от рантайма ещё не пришёл — вызов из теста или
	 * старая ревизия слота.
	 *
	 * @type {(key: string, vars?: Record<string, unknown>) => string}
	 */
	const defaultTranslate = (key, vars) => {
	  const text = ru[key]
	  if (typeof text !== 'string') return key
	  if (vars === undefined || vars === null) return text
	  return text.replace(/\{(\w+)\}/g, (match, name) => {
	    const value = vars[name]
	    return value === undefined || value === null ? match : String(value)
	  })
	}

	/**
	 * Собирает переводчик поверх одного словаря.
	 *
	 * Подстановка `{name}` сделана вручную, а не регуляркой по строке: так
	 * значение, содержащее фигурные скобки, не испортит разметку шаблона. Отсутствие
	 * значения в `vars` оставляет плейсхолдер как есть — такой текст заметнее, чем
	 * пустая строка, и виден в тестах.
	 *
	 * @param {Record<string, string>} [dict] - словарь (по умолчанию русский).
	 * @returns {(key: string, vars?: Record<string, unknown>) => string} переводчик.
	 */
	function createTranslate(dict = ru) {
	  return (key, vars) => {
	    const text = dict[key]
	    if (typeof text !== 'string') return key
	    if (vars === undefined || vars === null) return text
	    return text.replace(/\{(\w+)\}/g, (match, name) => {
	      const value = vars[name]
	      return value === undefined || value === null ? match : String(value)
	    })
	  }
	}

	// ── src/speakText.js ────────────────────────────────────────────
	// Что есть смысл произносить вслух.
	//
	// Ответ агента — не только проза. В нём разметка, следы работы инструментов,
	// ссылки, имена файлов и таблицы. Голос, который читает это вслух, мгновенно
	// перестаёт быть разговором: он тараторит «закрывающая скобка» и «жирный» и
	// произносит путь к файлу там, где человек ждёт ответа по делу.
	//
	// Функция живёт отдельно от синтеза, потому что нужна обеим половинам плагина:
	// хосту — на случай озвучки с его стороны, клиенту — чтобы решить, стоит ли
	// вообще будить голос. Проверять текст дважды, но по-разному, значит однажды
	// получить разные ответы на одном и том же ответе агента.

	/**
	 * Убирает из текста то, что не нужно произносить.
	 *
	 * Правила намеренно грубые: лучше прочитать лишнее слово, чем молча проглотить
	 * половину фразы. Дальше голос всё равно спотыкается о разметку, и это заметно,
	 * — а пропущенная мысль заметно хуже.
	 *
	 * @param {string} text - исходный текст.
	 * @returns {string} то, что есть смысл произнести.
	 */
	function speakable(text) {
	  if (typeof text !== 'string') return ''
	  return text
	    // Блоки кода: их не читают, а «закрывающая скобка» вслух звучит абсурдом.
	    .replace(/```[\s\S]*?```/g, ' ')
	    // Ссылка и её текст: читать текст, молчаливую часть — нет.
	    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
	    // Служебные метки инструментов вида <tool:call> и </tool:call>. Закрывающие
	    // обязательны в том же шаблоне: с двоеточием в имени они не похожи на
	    // обычный тег, и в голос попадали вместе с «выводом» внутри.
	    .replace(/<\/?[a-z][\w-]*:[^>]*>/gi, ' ')
	    // Обычные HTML-подобные теги: не читаем, но пробел сохраняем.
	    .replace(/<\/?[a-z][\w-]*(?:\s[^>]*)?>/gi, ' ')
	    // Таблицы читать нельзя — колонки сливаются в кашу из названий.
	    .replace(/^\s*\|.*\|\s*$/gm, ' ')
	    // Списки-маркеры и нумерация: голос читает «тире» вслух, а это шум.
	    .replace(/^\s*(?:[-*+]|\d+[.)])\s+/gm, '')
	    // Заголовки: решётки произносятся, а не смысл.
	    .replace(/^\s*#{1,6}\s+/gm, '')
	    // Акцент и код: жирный, курсив и кавычки.
	    .replace(/\*\*([^*]+)\*\*/g, '$1')
	    .replace(/(?<![A-Za-z0-9])[*_]([^*_]+)[*_](?![A-Za-z0-9])/g, '$1')
	    .replace(/`([^`\n]+)`/g, '$1')
	    .replace(/«([^»]*)»/g, '$1')
	    .replace(/„([^“]*)“/g, '$1')
	    // Горизонтальные разделители — тире вместо содержательного текста.
	    .replace(/^\s*(?:[-*_]\s*){3,}$/gm, ' ')
	    .replace(/\s+/g, ' ')
	    .trim()
	}

	/**
	 * Делит длинный ответ на части, удобные для произнесения подряд.
	 *
	 * SAPI и так умеет паузы, но очень длинный текст он начинает тараторить к
	 * концу. Разбивка по концам предложений сохраняет интонацию: голос ставит
	 * дыхание там, где человек поставил бы его сам.
	 *
	 * @param {string} text - подготовленный текст.
	 * @param {number} [limit] - предел длины части в знаках.
	 * @returns {string[]} части по порядку.
	 */
	function chunks(text, limit = 400) {
	  const clean = speakable(text)
	  if (clean === '') return []
	  const parts = []
	  let rest = clean
	  while (rest.length > limit) {
	    // Ищем последнюю точку или запятую в пределах лимита, но не в самом конце:
	    // иначе фраза разорвётся на выдохе посреди мысли.
	    let cut = -1
	    for (let at = Math.min(limit, rest.length - 1); at > limit / 2; at -= 1) {
	      const char = rest[at]
	      if (char === '.' || char === '?' || char === '!' || char === ';') {
	        cut = at + 1
	        break
	      }
	    }
	    if (cut === -1) cut = limit
	    parts.push(rest.slice(0, cut).trim())
	    rest = rest.slice(cut).trim()
	  }
	  if (rest !== '') parts.push(rest)
	  return parts.filter((part) => part !== '')
	}

	// ── src/client/api.js ───────────────────────────────────────────
	// Связь клиентской половины с host-маршрутами плагина.
	//
	// Своего RPC-канала у пакета нет: host-половина публикует обычные HTTP-маршруты
	// под префиксом `/voice-eternia`, а GUI открыт с того же origin, поэтому ходим
	// обычным fetch. Ключи API на хосте остаются на хосте — сюда приходит только
	// распознанный текст.

	/** Префикс маршрутов пакета. */
	const API_PREFIX = '/voice-eternia'

	/**
	 * Разбирает ответ маршрута.
	 *
	 * @param {Response} response - ответ fetch.
	 * @returns {Promise<object>} разобранное тело либо описание ошибки.
	 */
	async function parse(response) {
	  let payload
	  try {
	    payload = await response.json()
	  } catch {
	    return { ok: false, error: { code: 'bad-response', message: `Сервер ответил ${response.status}` } }
	  }
	  if (payload !== null && typeof payload === 'object') return payload
	  return { ok: false, error: { code: 'bad-response', message: 'Пустой ответ сервера.' } }
	}

	/**
	 * Отправляет POST без тела, ожидая ответ маршрута захвата.
	 *
	 * @param {string} url - адрес маршрута.
	 * @param {object} body - тело запроса.
	 * @returns {Promise<object>} разобранный ответ.
	 */
	async function post(url, body) {
	  try {
	    const response = await fetch(url, {
	      method: 'POST',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify(body),
	    })
	    return await parse(response)
	  } catch {
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Просит хост начать запись микрофона.
	 *
	 * Запись ведёт хост, а не страница: в окне Electron `getUserMedia` отказывает
	 * молча, потому что подписанная оболочка не пропускает разрешение `media`.
	 * На хосте запись делает внешняя программа, и браузер в процессе не участвует.
	 *
	 * @returns {Promise<{ ok: boolean, device?: string, maxSeconds?: number, error?: object }>}
	 */
	async function startRecording(options = {}) {
	  return post(`${API_PREFIX}/record/start`, { streaming: options.streaming === true })
	}

	/**
	 * Забирает очередную нарезанную фразу.
	 *
	 * Фразы режет хост: он слышит речь и сам решает, где она кончилась. Пока фраза
	 * не забрана, она лежит на хосте и в сеть не идёт.
	 *
	 * @returns {Promise<{ ok: boolean, value?: { audioBase64: string, durationMs: number } | null }>}
	 */
	async function takePhrase() {
	  try {
	    const response = await fetch(`${API_PREFIX}/record/phrase`, { method: 'GET' })
	    return await parse(response)
	  } catch {
	    return { ok: false }
	  }
	}

	/**
	 * Останавливает запись и забирает WAV.
	 *
	 * @returns {Promise<{ ok: boolean, audioBase64?: string, bytes?: number, error?: object }>}
	 */
	async function stopRecording() {
	  return post(`${API_PREFIX}/record/stop`, {})
	}

	/**
	 * Отменяет запись, ничего не возвращая.
	 *
	 * @returns {Promise<{ ok: boolean }>}
	 */
	async function cancelRecording() {
	  return post(`${API_PREFIX}/record/cancel`, {})
	}

	/**
	 * Читает состояние записи: идёт ли она и каков уровень сигнала.
	 *
	 * @returns {Promise<{ ok: boolean, value?: { recording: boolean, level: number, seconds: number }, error?: object }>}
	 */
	async function recordingStatus() {
	  try {
	    const response = await fetch(`${API_PREFIX}/record/status`, { method: 'GET' })
	    return await parse(response)
	  } catch {
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Читает настройки плагина, заданные в карточке.
	 *
	 * Клиенту нужны только те, что меняют поведение кнопки: показывать ли запасной
	 * путь через браузер и вставлять ли результат автоматически. Остальное
	 * (модель, промпт, микрофон) читает хост — он же делает запрос к моделям.
	 *
	 * @returns {Promise<object|null>} настройки либо null при недоступности.
	 */
	async function readConfig() {
	  try {
	    const response = await fetch(`${API_PREFIX}/config`, { method: 'GET' })
	    const payload = await parse(response)
	    if (payload.ok !== true || payload.value === null || typeof payload.value !== 'object') return null
	    return payload.value
	  } catch {
	    return null
	  }
	}

	/**
	 * Сохраняет настройки плагина.
	 *
	 * Хост принимает вложенные группы и раскладывает их в свой запасной файл, а
	 * `readSettings` перечитывает его на каждый запрос — поэтому правка видна
	 * сразу, без перезапуска DSH.
	 *
	 * @param {object} settings - настройки целиком.
	 * @returns {Promise<{ ok: boolean, value?: object, error?: object }>}
	 */
	async function writeConfig(settings) {
	  try {
	    const response = await fetch(`${API_PREFIX}/config`, {
	      method: 'PUT',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify(settings),
	    })
	    return await parse(response)
	  } catch {
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Отправляет аудио на распознавание.
	 *
	 * @param {object} options - параметры.
	 * @param {string} options.audioBase64 - WAV в base64.
	 * @param {AbortSignal} [options.signal] - отмена.
	 * @returns {Promise<{ ok: boolean, text?: string, empty?: boolean, tookMs?: number, error?: object }>} результат.
	 */
	async function transcribe({ audioBase64, signal }) {
	  try {
	    const response = await fetch(`${API_PREFIX}/transcribe`, {
	      method: 'POST',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify({ audioBase64 }),
	      signal,
	    })
	    return await parse(response)
	  } catch (failure) {
	    if (failure instanceof Error && failure.name === 'AbortError') {
	      return { ok: false, error: { code: 'aborted', message: 'Распознавание отменено.' } }
	    }
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Просит отполировать текст.
	 *
	 * Полировка — улучшение, а не обязательный шаг: при любой ошибке хост вернёт
	 * исходный текст, поэтому вызывающий код обязан смотреть на поле `polished`.
	 *
	 * @param {object} options - параметры.
	 * @param {string} options.text - сырой текст.
	 * @param {AbortSignal} [options.signal] - отмена.
	 * @returns {Promise<{ ok: boolean, text: string, polished?: boolean }>} результат.
	 */
	async function polish({ text, signal }) {
	  try {
	    const response = await fetch(`${API_PREFIX}/polish`, {
	      method: 'POST',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify({ text }),
	      signal,
	    })
	    const payload = await parse(response)
	    if (payload.ok === false) return { ok: false, text }
	    return { ok: true, text: typeof payload.text === 'string' ? payload.text : text, polished: payload.polished === true }
	  } catch {
	    return { ok: false, text }
	  }
	}

	/**
	 * Спрашивает у хоста адрес того же GUI для обычного браузера.
	 *
	 * Нужен, когда микрофон заблокирован оболочкой Electron: браузер по этому
	 * адресу показывает свой запрос доступа, и диктовка работает. Пустой `webUrl`
	 * означает «порт неизвестен» — тогда кнопку открытия не показываем, чтобы не
	 * вести пользователя по нерабочей ссылке.
	 *
	 * @returns {Promise<{ webUrl: string, port: number | null } | null>} адрес либо null.
	 */
	async function readEnvironment() {
	  try {
	    const response = await fetch(`${API_PREFIX}/env`, { method: 'GET' })
	    const payload = await parse(response)
	    if (payload.ok !== true || payload.value === null || typeof payload.value !== 'object') return null
	    return {
	      webUrl: typeof payload.value.webUrl === 'string' ? payload.value.webUrl : '',
	      port: typeof payload.value.port === 'number' ? payload.value.port : null,
	    }
	  } catch {
	    return null
	  }
	}

	/**
	 * Читает список моделей, настроенных в самом DSH.
	 *
	 * Зачем это нужно. Поле «модель» текстом — плохая просьба: `id` провайдера и
	 * точное имя модели человек помнить не обязан, а одна опечатка даёт молчаливый
	 * отказ при первой же записи. Хост читает список из профиля DSH — того самого,
	 * что виден в разделе «Модели», — и отдаёт его сюда для выпадающего списка.
	 *
	 * @returns {Promise<Array<object>|null>} модели либо null при недоступности.
	 */
	async function readModels() {
	  try {
	    const response = await fetch(`${API_PREFIX}/models`, { method: 'GET' })
	    const payload = await parse(response)
	    return payload.ok === true && Array.isArray(payload.models) ? payload.models : null
	  } catch {
	    return null
	  }
	}

	/**
	 * Читает имена записей с ключами доступа.
	 *
	 * Сами ключи сюда не приходят и прийти не могут: хост отдаёт только имена.
	 * Это и есть смысл списка — секрет вводят в хранилище DSH, а плагин лишь
	 * ссылается на запись по имени.
	 *
	 * @returns {Promise<Array<object>|null>} записи либо null при недоступности.
	 */
	async function readCredentials() {
	  try {
	    const response = await fetch(`${API_PREFIX}/credentials`, { method: 'GET' })
	    const payload = await parse(response)
	    return payload.ok === true && Array.isArray(payload.credentials) ? payload.credentials : null
	  } catch {
	    return null
	  }
	}

	/**
	 * Читает список голосов синтеза с машины.
	 *
	 * Список приходит с хоста, потому что голоса — часть системы, а не плагина:
	 * то, что стоит на этой Windows, и есть предложение. Имя голоса приходит
	 * ровно такое, каким его знает SAPI, иначе выбрать было бы нечем.
	 *
	 * @returns {Promise<Array<object>|null>} голоса либо null при недоступности.
	 */
	async function readVoices() {
	  try {
	    const response = await fetch(`${API_PREFIX}/voices`, { method: 'GET' })
	    // Отсутствие маршрута и пустой список — разные вещи, и человек должен
	    // видеть разное: первый говорит «перезапусти DSH», второй — «на этой
	    // машине нет голосов». null означает «не знаю», [] — «знаю, что пусто».
	    if (response.status === 404) return 'missing'
	    const payload = await parse(response)
	    return payload.ok === true && Array.isArray(payload.voices) ? payload.voices : 'missing'
	  } catch {
	    return 'missing'
	  }
	}

	/**
	 * Просит хоста произнести текст.
	 *
	 * @param {object} options - параметры.
	 * @param {string} options.text - что сказать.
	 * @param {string} [options.voice] - голос.
	 * @param {number} [options.rate] - темп.
	 * @param {number} [options.volume] - громкость.
	 * @returns {Promise<boolean>} получилось ли.
	 */
	async function speak({ text, voice, rate, volume }) {
	  try {
	    const response = await fetch(`${API_PREFIX}/speak`, {
	      method: 'POST',
	      headers: { 'content-type': 'application/json' },
	      body: JSON.stringify({ text, voice, rate, volume }),
	    })
	    const payload = await parse(response)
	    return payload.ok === true
	  } catch {
	    return false
	  }
	}

	/**
	 * Просит хоста замолчать.
	 *
	 * @returns {Promise<boolean>} получилось ли.
	 */
	async function stopSpeaking() {
	  try {
	    const response = await fetch(`${API_PREFIX}/stop-speaking`, { method: 'POST' })
	    const payload = await parse(response)
	    return payload.ok === true
	  } catch {
	    return false
	  }
	}


	// ── src/client/recorder.js ──────────────────────────────────────
	// Управление записью микрофона на стороне клиента.
	//
	// Запись ведёт ХОСТ, а не страница. Причина не в плагине: окно DSH Desktop —
	// это Electron, и подписанный `app.asar` пропускает через
	// `canGrantWindowPermission` только `clipboard-sanitized-write` и
	// `notifications`. Разрешения `media` в белом списке нет, поэтому `getUserMedia`
	// отказывает молча, без системного диалога, и никакой код плагина это не
	// обходит.
	//
	// Белый список относится к ОКНУ, а не к процессу хоста: хост — обычный Node,
	// где микрофон пишет внешняя программа (см. `src/capture.js`). Поэтому здесь
	// нет ни `getUserMedia`, ни `MediaRecorder`, ни пересэмплирования через Web
	// Audio — всё это браузерные обходные пути, которые в приложении не работают.
	// Клиент только спрашивает хоста: начать, остановить, где мы сейчас.
	//
	// Пересэмплирование тоже не нужно: хост пишет сразу 16 кГц mono — ровно тот
	// формат, который ждут облачные модели.



	/** Частота, которую ждут модели распознавания. */
	const TARGET_SAMPLE_RATE = 16000

	/** Максимальная длительность одной записи, секунды (защита от забытой записи). */
	const MAX_RECORD_SECONDS = 120

	/** Класс отказа, понятный человеку. */
	class RecorderError extends Error {
	  /**
	   * @param {string} kind - категория отказа.
	   * @param {string} message - текст для пользователя.
	   */
	  constructor(kind, message) {
	    super(message)
	    this.name = 'RecorderError'
	    this.kind = kind
	  }
	}

	/**
	 * Признак оболочки Electron.
	 *
	 * Нужен только для выбора текста отказа: в приложении микрофон берёт хост, в
	 * обычном браузере — по-прежнему `getUserMedia`, и там отказ означает совсем
	 * другое.
	 *
	 * @returns {boolean} верно ли, что страница открыта в Electron.
	 */
	function isDesktopShell() {
	  return typeof navigator !== 'undefined' && /electron/i.test(navigator.userAgent ?? '')
	}

	/**
	 * Проверяет, можно ли вести запись в этой среде.
	 *
	 * Раньше здесь проверялся `navigator.mediaDevices`. Теперь запись идёт через
	 * хост, поэтому проверять нечего: если хост на месте — пишем, если нет —
	 * отказ придёт от маршрута с понятным текстом. Оставляем функцию, потому что
	 * вызывающий код ждёт её ответа, и она же объясняет пользователю случай, когда
	 * плагин открыли вообще без хоста.
	 *
	 * @returns {{ available: boolean, reason: string }} доступность и причина.
	 */
	function probeSupport() {
	  if (typeof fetch !== 'function') {
	    return { available: false, reason: 'offline' }
	  }
	  return { available: true, reason: '' }
	}

	/**
	 * Читает имя ошибки, не полагаясь на `instanceof`.
	 *
	 * `instanceof Error` ненадёжен сразу по двум причинам: ошибка может прийти из
	 * другого realm (iframe, песочница), где прототип другой. Читаем поле `name`
	 * напрямую.
	 *
	 * @param {unknown} failure - произвольное значение.
	 * @returns {{ name: string, message: string }} имя и текст.
	 */
	function describeFailure(failure) {
	  if (failure === null || typeof failure !== 'object') {
	    return { name: '', message: String(failure) }
	  }
	  const name = typeof failure.name === 'string' ? failure.name : ''
	  const message = typeof failure.message === 'string' ? failure.message : ''
	  return { name, message }
	}

	/**
	 * Переводит отказ в текст для пользователя.
	 *
	 * Коды приходят с хоста и уже человекочитаемы, поэтому подробности оракула о
	 * них мы сохраняем, а код без разбора отдаём как есть. Подсказка зависит от
	 * среды: в браузере отказ почти всегда значит «пользователь закрыл диалог или
	 * запретил микрофон в настройках сайта», и это другой совет.
	 *
	 * @param {unknown} failure - отказ: `RecorderError` или ответ маршрута.
	 * @param {(key: string, vars?: object) => string} [t] - переводчик словаря.
	 * @returns {RecorderError} ошибка с категорией.
	 */
	function classifyFailure(failure, t = defaultTranslate) {
	  if (failure instanceof RecorderError) return failure
	  const { name, message } = describeFailure(failure)
	  const code = typeof failure?.error?.code === 'string' ? failure.error.code : ''
	  const detail = typeof failure?.error?.message === 'string' && failure.error.message !== ''
	    ? failure.error.message
	    : message

	  if (name === 'NotAllowedError' || name === 'SecurityError') {
	    return new RecorderError(
	      'denied',
	      t(isDesktopShell() ? 'error.deniedDesktop' : 'error.deniedSite'),
	    )
	  }
	  if (code === 'nodevice' || name === 'NotFoundError' || name === 'OverconstrainedError') {
	    return new RecorderError('nodevice', t('error.noDevice'))
	  }
	  if (code === 'busy' || name === 'NotReadableError') {
	    return new RecorderError('busy', t('error.busy'))
	  }
	  // Код от хоста уже содержит причину («На машине нет ffmpeg…»): переписывать
	  // его своим текстом значило бы потерять полезную подробность.
	  if (detail !== '') return new RecorderError(code === '' ? 'unknown' : code, detail)
	  return new RecorderError('unknown', t('error.unknown'))
	}

	/**
	 * Короткий путь для мест, где нужна только строка сообщения.
	 *
	 * @param {unknown} failure - отказ.
	 * @param {(key: string, vars?: object) => string} [t] - переводчик.
	 * @returns {string} текст для пользователя.
	 */
	function classifyFailureMessage(failure, t = defaultTranslate) {
	  return classifyFailure(failure, t).message
	}

	/**
	 * Кодирует сэмплы в WAV: 16 бит, mono, RIFF-заголовок 44 байта.
	 *
	 * Запись с микрофона приходит с хоста уже в WAV, поэтому функция нужна для
	 * синтетических сэмплов и для проверок формата; на пути диктовки её не
	 * вызывают.
	 *
	 * @param {Float32Array} samples - сэмплы в диапазоне [-1, 1].
	 * @returns {Uint8Array} готовый файл.
	 */
	function encodeWave(samples) {
	  const bytes = new Uint8Array(44 + samples.length * 2)
	  const view = new DataView(bytes.buffer)
	  const text = (at, value) => {
	    for (let i = 0; i < value.length; i += 1) bytes[at + i] = value.charCodeAt(i)
	  }
	  text(0, 'RIFF')
	  view.setUint32(4, bytes.length - 8, true)
	  text(8, 'WAVE')
	  text(12, 'fmt ')
	  view.setUint32(16, 16, true)
	  view.setUint16(20, 1, true) // PCM
	  view.setUint16(22, 1, true) // mono
	  view.setUint32(24, TARGET_SAMPLE_RATE, true)
	  view.setUint32(28, TARGET_SAMPLE_RATE * 2, true)
	  view.setUint16(32, 2, true)
	  view.setUint16(34, 16, true)
	  text(36, 'data')
	  view.setUint32(40, samples.length * 2, true)
	  for (let i = 0; i < samples.length; i += 1) {
	    // Ограничение асимметричное, как требует PCM16: −32768 влезает в знаковый
	    // 16-битный тип, а +32768 не влезает и стал бы −32768 — то есть тихий
	    // всплеск тихо превратился бы в резкий щелчок в начале сигнала.
	    const sample = samples[i]
	    const value = sample <= -1 ? -32768 : sample >= 1 ? 32767 : Math.round(sample * 32767)
	    view.setInt16(44 + i * 2, value, true)
	  }
	  return bytes
	}

	/**
	 * Переводит байты в base64 без `btoa` над большим массивом.
	 *
	 * @param {Uint8Array|Buffer} bytes - данные.
	 * @returns {string} base64.
	 */
	function toBase64(bytes) {
	  let binary = ''
	  const step = 0x8000
	  for (let i = 0; i < bytes.length; i += step) {
	    binary += String.fromCharCode(...bytes.subarray(i, Math.min(i + step, bytes.length)))
	  }
	  return btoa(binary)
	}

	/**
	 * Одна запись с микрофона.
	 *
	 * Жизненный цикл: `start()` → `stop()` → освобождение. Отмена, сбой и
	 * выгрузка плагина ведут в один и тот же `dispose()`, поэтому повторный вызов
	 * безопасен: освобождение обязано быть идемпотентным.
	 *
	 * Уровень сигнала приходит опросом маршрута: поток живёт на хосте, и подписаться
	 * на него из страницы нельзя. Опрос идёт четыре раза в секунду — этого хватает
	 * для живого индикатора и незаметно для сети.
	 */
	class Recording {
	  constructor() {
	    this.phase = 'idle'
	    this.startedAt = 0
	    this.maxSeconds = MAX_RECORD_SECONDS
	    this.onLevel = null
	    this.onFailure = null
	    this.levelTimer = 0
	    this.disposed = false
	    this.seconds = 0
	  }

	  /**
	   * Просит хост начать запись и включает опрос уровня.
	   *
	   * @param {object} options - параметры.
	   * @param {(kind: string, message: string) => void} [options.onFailure] - обработчик обрыва.
	   * @param {(level: number, bands?: number[]) => void} [options.onLevel] - уровень сигнала 0..1 и полосы гистограммы.
	   */
	  async start({ onFailure, onLevel } = {}) {
	    this.onLevel = typeof onLevel === 'function' ? onLevel : null
	    this.onFailure = typeof onFailure === 'function' ? onFailure : null

	    const support = probeSupport()
	    if (!support.available) {
	      throw new RecorderError('unsupported', 'Хост недоступен — плагин работает только в DSH.')
	    }

	    const answer = await startRecording()
	    if (this.disposed) {
	      // Компонент разобрали, пока шёл запрос: запись надо погасить, иначе
	      // микрофон останется открытым после выгрузки плагина.
	      void cancelRecording()
	      return
	    }
	    if (answer.ok !== true) throw classifyFailure(answer)

	    this.phase = 'recording'
	    this.startedAt = Date.now()
	    if (typeof answer.value?.maxSeconds === 'number') this.maxSeconds = answer.value.maxSeconds
	    this.levelTimer = setInterval(() => { void this.poll() }, 250)
	  }

	  /**
	   * Один опрос состояния: обновляет уровень и ловит обрыв записи на хосте.
	   *
	   * @returns {Promise<void>}
	 */
	  async poll() {
	    if (this.phase !== 'recording') return
	    const answer = await recordingStatus()
	    if (this.disposed) return
	    if (answer.ok !== true) return
	    const state = answer.value
	    if (state?.recording !== true) {
	      // Хост закончил запись сам — например, упёрся в лимит времени. Молчать
	      // тут нельзя: пользователь смотрел бы на «идёт запись» вечно.
	      this.phase = 'ended'
	      this.clearTimer()
	      this.onFailure?.('ended', '')
	      return
	    }
	    this.seconds = state.seconds ?? 0
	    this.onLevel?.(state.level ?? 0, Array.isArray(state.bands) ? state.bands : [])
	  }

	  /**
	   * Останавливает запись и отдаёт готовое аудио.
	   *
	   * Base64 не декодируется и не перекодируется: хост уже отдал WAV в base64,
	   * ровно в том виде, в каком его принимает маршрат распознавания. Обратное
	   * преобразование здесь было бы лишним копированием мегабайта данных.
	   *
	   * @returns {Promise<{ audioBase64: string, bytes: number }>} аудио для распознавания.
	   */
	  async stop() {
	    if (this.phase === 'stopped') throw new RecorderError('not-recording', 'Запись уже остановлена')
	    this.clearTimer()
	    const answer = await stopRecording()
	    if (answer.ok !== true) throw classifyFailure(answer)
	    this.phase = 'stopped'
	    if (typeof answer.value?.audioBase64 !== 'string') {
	      throw new RecorderError('lost', 'Хост вернул запись без данных.')
	    }
	    return {
	      audioBase64: answer.value.audioBase64,
	      bytes: answer.value.bytes ?? 0,
	    }
	  }

	  /** Останавливает таймер опроса, если он идёт. */
	  clearTimer() {
	    if (this.levelTimer !== 0) {
	      clearInterval(this.levelTimer)
	      this.levelTimer = 0
	    }
	  }

	  /**
	   * Гасит запись: снимает таймер и просит хост прекратить писать.
	   *
	   * Идемпотентно — к нему обращаются и отмена, и выгрузка плагина.
	   *
	   * @returns {void}
	   */
	  dispose() {
	    if (this.disposed) return
	    this.disposed = true
	    this.clearTimer()
	    if (this.phase === 'recording') void cancelRecording()
	    this.phase = 'idle'
	  }
	}

	/**
	 * Перечисляет микрофоны.
	 *
	 * Функция сохранена ради прежнего контракта: UI больше её не зовёт — захват
	 * идёт на хосте и устройство выбирает он, — но плагины, встроившие чужой код
	 * с этим импортом, продолжат собираться.
	 *
	 * @returns {Promise<string[]>} всегда пустой список.
	 */
	async function listMicrophones() {
	  return []
	}

	// ── src/client/talk.js ──────────────────────────────────────────
	// Разговорный режим: человек говорит, ответ приходит голосом.
	//
	// Отличие от диктовки. Диктовка — это «нажал, сказал, посмотрел в поле»:
	// человек каждое предложение отправляет руками. Разговор — это когда запись
	// идёт непрерывно, а система сама решает, где кончилась фраза, распознаёт её и
	// отправляет в беседу. Именно здесь появляется ощущение разговора: пауза вместо
	// кнопки.
	//
	// Задержка складывается из трёх частей и это важно понимать честно:
	//   пауза до конца фразы (по умолчанию 1.2 сек) → распознавание (~1 сек) →
	//   ответ агента (его дело) → озвучка (локальная, десятки миллисекунд).
	// Итого цикл 2–4 секунды. Сократить можно паузой и моделью распознавания, но не
	// ценой надёжности: нарезать фразу раньше, чем человек договорил, хуже, чем
	// ждать.
	//
	// Никакого `getUserMedia` здесь нет по той же причине, что и в диктовке:
	// окно DSH Desktop — Electron с белым списком разрешений, где нет `media`.
	// Всё, что здесь происходит, — опрос хоста и отправка текста.




	/** Как часто опрашиваем состояние, мс. Для гистограммы этого достаточно. */
	const POLL_MS = 120

	/**
	 * Один разговор: запись, нарезка фраз, отправка.
	 *
	 * Жизненный цикл тот же, что у диктовки: `start()` → работает → `stop()`.
	 * Отмена, сбой и выгрузка плагина ведут в один `dispose()`, поэтому повторный
	 * вызов безопасен: освобождение обязано быть идемпотентным, иначе микрофон
	 * остался бы открытым после выгрузки.
	 */
	class Talk {
	  /**
	   * @param {object} [options] - настройки.
	   * @param {object} [options.settings] - настройки плагина.
	   * @param {(text: string) => void} [options.onSend] - отправка текста в беседу.
	   * @param {(status: object) => void} [options.onState] - смена состояния панели.
	   * @param {(bands: number[]) => void} [options.onBands] - гистограмма голоса.
	   * @param {(kind: string, message: string) => void} [options.onFailure] - обрыв.
	   * @param {(text: string) => void} [options.onPartial] - услышанное текстом.
	   */
	  constructor(options = {}) {
	    this.settings = options.settings ?? {}
	    this.onSend = typeof options.onSend === 'function' ? options.onSend : null
	    this.onState = typeof options.onState === 'function' ? options.onState : null
	    this.onBands = typeof options.onBands === 'function' ? options.onBands : null
	    this.onFailure = typeof options.onFailure === 'function' ? options.onFailure : null
	    this.onPartial = typeof options.onPartial === 'function' ? options.onPartial : null
	    this.recognizer = typeof options.recognize === 'function' ? options.recognize : null

	    this.phase = 'idle'
	    this.timer = 0
	    this.disposed = false
	    this.bands = []
	    this.speaking = false
	    this.pending = 0
	    /** Фраза уже в работе: две одновременно нельзя, иначе ответы будут переплетаться. */
	    this.busy = false
	    /** Что сейчас произносится — нужно, чтобы замолчать на перебивании. */
	    this.talking = false
	  }

	  /**
	   * Начинает разговор.
	   *
	   * @returns {Promise<void>}
	   */
	  async start() {
	    if (this.disposed) throw new Error('разговор уже закрыт')
	    if (this.phase !== 'idle') throw new Error('разговор уже идёт')

	    const answer = await startRecording({ streaming: true })
	    if (this.disposed) {
	      // Разобрали, пока шёл запрос: микрофон не должен остаться открытым.
	      void cancelRecording()
	      return
	    }
	    if (answer.ok !== true) throw classifyFailure(answer)

	    this.phase = 'listening'
	    this.emitState()
	    this.timer = setInterval(() => { void this.poll() }, POLL_MS)
	  }

	  /**
	   * Один опрос: гистограмма, состояние речи и забор готовых фраз.
	   *
	   * @returns {Promise<void>}
	   */
	  async poll() {
	    if (this.phase !== 'listening') return
	    const answer = await recordingStatus()
	    if (this.disposed || answer.ok !== true) return
	    const state = answer.value ?? {}

	    if (state.recording !== true) {
	      // Хост закончил запись сам. Молчать нельзя: человек будет думать, что его
	      // слушают, а его уже не слушают.
	      this.phase = 'ended'
	      this.clearTimer()
	      this.emitState()
	      this.onFailure?.('ended', '')
	      return
	    }

	    if (Array.isArray(state.bands) && state.bands.length > 0) {
	      this.bands = state.bands
	      this.onBands?.(state.bands)
	    }
	    this.speaking = state.speaking === true
	    this.pending = typeof state.pending === 'number' ? state.pending : 0

	    // Фраза отправляется по одной. Вторая берётся, когда первая ушла: пока
	    // распознавание и ответ идут, человек может уже договорить следующую.
	    if (this.pending > 0 && this.busy !== true) {
	      this.busy = true
	      // Пока фраза распознаётся, панель обязана это показать: молчание в
	      // несколько секунд человек читает как зависание, хотя сеть работает.
	      this.phase = 'recognizing'
	      this.emitState()
	      void this.takeAndSend()
	    }
	  }

	  /**
	   * Забирает фразу, распознаёт и отправляет в беседу.
	   *
	   * @returns {Promise<void>}
	   */
	  async takeAndSend() {
	    try {
	      const answer = await takePhrase()
	      if (this.disposed) return
	      if (answer.ok !== true || answer.value === null || answer.value === undefined) return
	      const audio = answer.value.audioBase64
	      if (typeof audio !== 'string' || audio === '') return
	      const text = await this.recognize(audio)
	      if (this.disposed) return
	      const clean = typeof text === 'string' ? text.trim() : ''
	      // Пустой результат — это не ошибка: человек выдохнул, а не сказал слова.
	      // Отправлять пустоту в беседу нельзя, от неё ломается история диалога.
	      if (clean === '') return
	      this.onSend?.(clean)
	    } catch (failure) {
	      if (this.disposed === false) {
	        const { message } = describeFailure(failure)
	        this.onFailure?.('recognize', message)
	      }
	    } finally {
	      this.busy = false
	      // Возвращаемся к слушанию: следующая фраза может прийти в любой момент.
	      if (this.disposed === false) {
	        this.phase = 'listening'
	        this.emitState()
	      }
	    }
	  }

	  /**
	   * Распознаёт фразу.
	   *
	   * Распознавание передаётся снаружи: маршрут живёт в другом слое, и знать про
	   * него здесь незачем — достаточно знать, что фраза превратится в текст.
	   *
	   * @param {string} audioBase64 - звук фразы.
	   * @returns {Promise<string>} распознанный текст.
	   */
	  async recognize(audioBase64) {
	    if (typeof this.recognizer !== 'function') return ''
	    return await this.recognizer(audioBase64)
	  }

	  /**
	   * Произносит ответ агента вслух.
	   *
	   * Голос берётся из настроек, но если настройка не задана, хост выберет голос
	   * системы. Текст очищается от разметки: читать вслух «закрывающая скобка» или
	   * имя файла из ссылки — не разговор, а рябь в колонках.
	   *
	   * @param {string} text - ответ агента.
	   * @returns {Promise<boolean>} удалось ли.
	   */
	  async say(text) {
	    const speech = this.settings.speech ?? {}
	    if (speech.enabled === false) return false
	    const sayable = speakable(text)
	    if (sayable === '') return false
	    this.talking = true
	    this.emitState()
	    const done = await speak({
	      text: sayable,
	      voice: typeof speech.voice === 'string' ? speech.voice : '',
	      rate: typeof speech.rate === 'number' ? speech.rate : 0,
	      volume: typeof speech.volume === 'number' ? speech.volume : 100,
	    })
	    this.talking = false
	    this.emitState()
	    return done
	  }

	  /**
	   * Замолчать.
	   *
	   * В разговоре это не украшение: человек перебивает голос, чтобы ответ не
	   * заглушал его собственную фразу, — иначе приходится ждать конца длинного
	   * ответа, чтобы задать вопрос.
	   *
	   * @returns {Promise<void>}
	   */
	  async hush() {
	    if (this.talking === false) return
	    await stopSpeaking()
	    this.talking = false
	    this.emitState()
	  }

	  /**
	   * Останавливает разговор.
	   *
	   * @returns {Promise<void>}
	   */
	  async stop() {
	    this.phase = 'stopped'
	    this.clearTimer()
	    await this.hush()
	    void cancelRecording()
	    this.emitState()
	  }

	  /** Останавливает таймер опроса, если он идёт. */
	  clearTimer() {
	    if (this.timer !== 0) {
	      clearInterval(this.timer)
	      this.timer = 0
	    }
	  }

	  /** Сообщает панели о состоянии: слушаем, говорит человек или говорит голос. */
	  emitState() {
	    this.onState?.({
	      phase: this.phase,
	      speaking: this.speaking,
	      talking: this.talking,
	      pending: this.pending,
	    })
	  }

	  /**
	   * Гасит разговор: снимает таймер, останавливает микрофон и голос.
	   *
	   * Идемпотентно — к нему обращаются и остановка, и выгрузка плагина.
	   *
	   * @returns {void}
	   */
	  dispose() {
	    if (this.disposed) return
	    this.disposed = true
	    this.clearTimer()
	    this.phase = 'idle'
	    void stopSpeaking()
	    void cancelRecording()
	  }
	}

	// ── src/client/echo.js ──────────────────────────────────────────
	// Наблюдатель за ответами агента: чтобы голос знал, что именно сказать.
	//
	// Откуда берётся текст ответа. У плагина нет доступа к потоку агента: клиентские
	// слоты отдают состояние беседы, но не текст сообщений, а сервис запросов сессии
	// читает сохранённые на диске сессии, а не живую. Прямой путь закрыт, и любая
	// попытка вытащить текст из внутренних сторов DSH упрётся в чужой приватный код.
	//
	// Поэтому наблюдаем за DOM. Это осознанный компромисс, и он не так страшен, как
	// кажется: у сообщений человека в чате есть модификатор класса `user`, а у
	// ответа агента — нет. Значит «последний абзац без этого класса» — это ответ.
	// Наблюдатель молчит, пока не увидит новый текст, и не трогает ничего: он
	// только читает.
	//
	// Что делает с текстом. Ждёт, пока текст перестанет меняться: агент пишет по
	// мере генерации, и произносить текст, который ещё дописывается, значит
	// прочитать половину предложения и остановиться.

	/** Сколько тишины считается концом ответа, мс. */
	const ANSWER_SETTLE_MS = 900

	/** Как часто проверяется, что текст перестал меняться, мс. */
	const CHECK_MS = 120

	/**
	 * Селектор области чата в интерфейсе DSH.
	 *
	 * Атрибут называется `data-conversation-region` — БЕЗ префикса `dsh-`. Ошибка в
	 * один префикс стоила разговора целиком: наблюдатель не находил область чата,
	 * `start()` возвращал false, и ответ агента не произносился никогда. При этом
	 * запись и отправка работали, поэтому выглядело это как «я говорю, а в ответ
	 * тишина» — то есть как поломка диалога, а не как неверный селектор.
	 */
	const CHAT_REGION = '[data-conversation-region="chat"]'

	/**
	 * Наблюдатель за чатом.
	 *
	 * Наблюдение начинается по запросу и снимается по запросу же: держать
	 * MutationObserver на странице, когда озвучка выключена, незачем — это лишняя
	 * работа браузера в чужом интерфейсе.
	 */
	class ReplyWatcher {
	  /**
	   * @param {object} [options] - параметры.
	   * @param {(text: string) => void} [options.onReply] - новый ответ агента.
	   */
	  constructor(options = {}) {
	    this.onReply = typeof options.onReply === 'function' ? options.onReply : null
	    this.observer = null
	    this.pending = null
	    this.timer = 0
	    this.lastSeen = ''
	    this.armed = false
	  }

	  /**
	   * Начинает наблюдение.
	   *
	   * @returns {boolean} удалось ли начать.
	   */
	  start() {
	    if (this.observer !== null) return true
	    if (typeof MutationObserver !== 'function') return false
	    const root = typeof document === 'undefined' ? null : document.querySelector(CHAT_REGION)
	    // Области чата может не быть ещё: сессия открывается позже. Тогда ждём
	    // появления и тогда включаемся, иначе озвучка молча не работала бы.
	    if (root === null) return false
	    this.armed = true
	    this.observer = new MutationObserver(() => { this.scan(root) })
	    this.observer.observe(root, { childList: true, subtree: true, characterData: true })
	    this.lastSeen = this.latestReply(root)
	    return true
	  }

	  /**
	   * Останавливает наблюдение.
	   *
	   * @returns {void}
	   */
	  stop() {
	    this.armed = false
	    if (this.observer !== null) {
	      this.observer.disconnect()
	      this.observer = null
	    }
	    if (this.timer !== 0) {
	      clearTimeout(this.timer)
	      this.timer = 0
	    }
	    this.pending = null
	  }

	  /**
	   * Ищет новый ответ агента в области чата.
	   *
	   * @param {Element} root - область чата.
	   * @returns {void}
	   */
	  scan(root) {
	    const text = this.latestReply(root)
	    if (text === '' || text === this.lastSeen) return
	    this.lastSeen = text
	    this.pending = text
	    if (this.timer !== 0) clearTimeout(this.timer)
	    this.timer = setTimeout(() => { this.settle() }, CHECK_MS)
	  }

	  /**
	   * Проверяет, что ответ перестал меняться.
	   *
	   * @returns {void}
	   */
	  settle() {
	    this.timer = 0
	    if (this.armed === false || this.pending === null) return
	    const root = typeof document === 'undefined' ? null : document.querySelector(CHAT_REGION)
	    const text = root === null ? this.pending : this.latestReply(root)
	    if (text === this.pending) {
	      // Текст замер — значит ответ дописан и можно говорить.
	      this.onReply?.(text)
	      this.pending = null
	      return
	    }
	    // Ещё пишет: ждём дальше.
	    this.pending = text
	    this.timer = setTimeout(() => { this.settle() }, CHECK_MS)
	  }

	  /**
	   * Достаёт текст последнего ответа агента.
	   *
	   * @param {Element} root - область чата.
	   * @returns {string} текст или пусто.
	   */
	  latestReply(root) {
	    const nodes = root.querySelectorAll('[class*="MessageItem"], [data-message], article, li')
	    for (let index = nodes.length - 1; index >= 0; index -= 1) {
	      const node = nodes[index]
	      if (node === null || node === undefined) continue
	      // Сообщение человека — не ответ. Иначе плагин читал бы вслух слова,
	      // которые человек только что произнёс, и разговаривал бы сам с собой.
	      const classes = typeof node.className === 'string' ? node.className : ''
	      if (/(^|\s|\.)user(\s|$)/.test(classes)) continue
	      const text = normalize(node.innerText ?? node.textContent ?? '')
	      if (text !== '') return text
	    }
	    return ''
	  }
	}

	/**
	 * Приводит текст узла к одной строке без ролей пробелов.
	 *
	 * @param {string} text - исходный текст.
	 * @returns {string} нормализованный текст.
	 */
	function normalize(text) {
	  return String(text).replace(/\s+/g, ' ').trim()
	}


